/** Original optional diary review. No record omission is interpreted as wake without explicit confirmation. */
public final class SRIActivity extends Activity {
    private final ExecutorService reader=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private Records.Factory records;private SRIReviews.Factory preferences;private SRIReviews.Snapshot snapshot;
    private ZoneId zone;private LocalDate selected;private boolean reviewing,allSleep,noTravel,loading,resumed;private String draftFingerprint="",draftKey="",error="",operation;private int generation;private long seenChanges;private RecordCalendar calendar;private Dialog explanation;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);records=Records.factory;preferences=SRIReviews.factory;try{zone=ZoneId.of(state==null?SRIReviews.viewZone(this):state.getString("zone",SRIReviews.viewZone(this)));selected=state==null?LocalDate.now(zone).minusDays(1):LocalDate.parse(state.getString("selected",LocalDate.now(zone).minusDays(1).toString()));if(state!=null){reviewing=state.getBoolean("reviewing");allSleep=state.getBoolean("allSleep");noTravel=state.getBoolean("noTravel");draftFingerprint=state.getString("draftFingerprint","");draftKey=state.getString("draftKey","");error=state.getString("error","");operation=state.getString("operation");}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);render();}catch(RuntimeException invalid){zone=ZoneId.systemDefault();selected=LocalDate.now(zone).minusDays(1);error="The selected review day could not be restored. Choose it again.";render();}}
    @Override protected void onResume(){super.onResume();resumed=true;load();observe();main.post(watch);}@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);main.removeCallbacks(watch);super.onPause();}
    private void load(){loading=true;int request=++generation;long sourceChange=SRIReviews.generation();LocalDate date=selected;ZoneId clock=zone;Context app=getApplicationContext();Records.Factory pinned=records;SRIReviews.Factory prefs=preferences;render();reader.execute(()->{try{SRIReviews.Snapshot value=SRIReviews.read(app,pinned,prefs,date,clock);runOnUiThread(()->{if(isDestroyed()||isFinishing()||request!=generation)return;boolean sameDraft=draftKey.equals(value.selected.key())&&draftFingerprint.equals(value.selected.fingerprint);if(!sameDraft){boolean changed=!draftFingerprint.isEmpty()&&draftKey.equals(value.selected.key());SRIReviews.Review saved=value.confirmation();boolean confirmed=saved!=null&&saved.matches(value.selected)&&value.selected.eligible();allSleep=noTravel=confirmed;draftFingerprint=value.selected.fingerprint;draftKey=value.selected.key();if(changed&&reviewing&&operation==null)error="The saved periods changed. Review this updated day before confirming.";}snapshot=value;seenChanges=sourceChange;loading=false;render();});}catch(Exception problem){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;loading=false;snapshot=null;error=problem.getMessage()==null?"Sleep records could not be opened. No regularity value was calculated.":problem.getMessage();render();});}});}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,reviewing?"Review a complete day":"Reviewed sleep regularity",this::back);Design.space(body,14);if(snapshot==null){Design.text(body,loading?"Loading saved sleep periods…":error.isEmpty()?"No review data loaded.":error,15,500,Design.MUTED);if(!loading)Design.button(body,"Reload records",true,this::load);return;}if(loading)Design.text(body,"Refreshing records · previous figures shown",12,500,Design.BROWN);if(reviewing)review(body);else overview(body);}
    private void overview(LinearLayout body){SRIModel.Summary summary=snapshot.summary;Design.text(body,"Diary-based SRI",17,600,Design.MUTED);Design.text(body,summary.score==null?"—":String.format(Locale.getDefault(),"%.1f",summary.score),54,700,Design.INK);Design.text(body,summary.score==null?"Review at least 7 adjacent day pairs before calculating.":"Same sleep/wake state 24 hours apart · self-reported",13,400,Design.MUTED);Design.space(body,14);PlanActivity.detail(body,"calendar","Confirmed unchanged days",null,summary.confirmedDays+" / 30",null);PlanActivity.detail(body,"clock","Comparable 24-hour day pairs",null,summary.pairs+" / "+summary.possiblePairs,null);PlanActivity.detail(body,"report","Same-state minute centers",null,summary.sameMinutes+" / "+summary.comparedMinutes,null);Design.text(body,"Unknown, changed, travel and clock-change days do not contribute. Missing daytime records are never silently treated as awake.",12,400,Design.MUTED);if(summary.changedDays>0)Design.text(body,summary.changedDays+" prior confirmations need another review.",13,500,Design.BROWN);zoneRow(body);Design.space(body,10);Design.button(body,"Review yesterday",true,()->open(LocalDate.now(zone).minusDays(1)));Design.button(body,"Choose a past day",false,this::calendar);Design.space(body,14);Design.text(body,"Past 30 complete calendar days",17,600,Design.INK);for(int i=summary.days.size()-1;i>=0;i--){SRIModel.Row row=summary.days.get(i);PlanActivity.detail(body,"calendar",row.day.date.format(DateTimeFormatter.ofPattern("EEE d MMM",Locale.getDefault())),row.status,RecordUi.duration(row.day.sleepMillis),()->open(row.day.date));}Design.space(body,12);Design.text(body,"A review confirms the entire day, including naps and awake edits. It is a diary statement, not verified sensor sleep/wake or a clinical regularity category.",12,400,Design.MUTED);Design.text(body,"Up to 90 confirmations are retained for 90 days. Only the latest 30 days in the selected zone enter this calculation."+(snapshot.saved.expired>0?" "+snapshot.saved.expired+" outside-window confirmations were ignored.":""),11,400,Design.MUTED);method(body);if(!error.isEmpty())Design.text(body,error,13,500,Design.BROWN);}
    private void zoneRow(LinearLayout body){Design.space(body,8);PlanActivity.detail(body,"clock","Review time zone",null,zone.getId(),()->{if(operation!=null)return;List<String> values=new ArrayList<>(snapshot.capture.zones);if(!values.contains(zone.getId()))values.add(zone.getId());String[] labels=values.toArray(new String[0]);int index=values.indexOf(zone.getId());if(explanation!=null)explanation.dismiss();explanation=SleepPicker.choices(this,"Review time zone",labels,index,n->{zone=ZoneId.of(values.get(n));SRIReviews.viewZone(this,zone.getId());selected=LocalDate.now(zone).minusDays(1);allSleep=noTravel=false;draftKey=draftFingerprint="";snapshot=null;error="";load();});});}
    private void review(LinearLayout body){SRIModel.Day day=snapshot.selected;SRIReviews.Review prior=snapshot.confirmation();boolean confirmed=prior!=null&&prior.matches(day)&&day.eligible();Design.text(body,day.date.format(DateTimeFormatter.ofPattern("EEE d MMM uuuu",Locale.getDefault())),23,600,Design.INK);Design.text(body,zone.getId()+" · midnight to midnight",12,500,Design.MUTED);Design.space(body,10);PlanActivity.detail(body,"moon","Listed sleep · union of all periods",null,RecordUi.duration(day.sleepMillis),null);Design.text(body,"Overlaps count once. Naps, trims, pauses, accepted awake edits and provider awake periods use the same retained coverage as the record editor.",12,400,Design.MUTED);Design.space(body,12);if(day.sleep.isEmpty())Design.text(body,"No retained sleep intervals are listed. That does not by itself mean you were awake.",14,500,Design.BROWN);else{StringBuilder intervals=new StringBuilder();for(RecordIntervals.Span span:day.sleep){if(intervals.length()>0)intervals.append('\n');intervals.append(time(span.start,day)).append(" – ").append(time(span.end,day));}Design.text(body,intervals.toString(),16,500,Design.INK);}Design.space(body,12);Design.text(body,confirmed?"Complete day already confirmed and unchanged":prior!=null?"Previous confirmation invalid · records changed":"Remaining time is unknown until you confirm it",13,600,Design.BROWN);if(!day.issue.isEmpty())Design.text(body,day.issue,13,500,Design.BROWN);Design.space(body,12);
        Switch sleep=Design.toggle(body,day.sleep.isEmpty()?"I had no sleep on this day":"All my sleep that day is listed",day.sleep.isEmpty()?"I confirm I was awake for the entire calendar day.":"Including naps. I confirm all remaining time was awake.",allSleep,on->allSleep=on);Switch travel=Design.toggle(body,"No time-zone travel that day","I stayed in this review time zone for the entire day.",noTravel,on->noTravel=on);sleep.setEnabled(!loading&&operation==null&&day.eligible());travel.setEnabled(!loading&&operation==null&&day.eligible());Design.space(body,10);Design.text(body,"If anything is missing, add or edit the sleep record first. Do not confirm an incomplete list.",12,400,Design.MUTED);Design.button(body,"Add missing sleep",false,()->startActivity(RecordUi.intent(this,RecordEditorActivity.class)));Set<Long> ids=new HashSet<>();int shown=0;for(RecordEntry record:day.records){if(!ids.add(record.id))continue;if(shown++>=30){Design.button(body,"Open complete sleep history",false,()->startActivity(RecordUi.intent(this,HistoryActivity.class)));break;}Design.item(body,"file","Edit sleep record #"+record.id,record.provenance(),()->startActivity(RecordUi.intent(this,RecordEditorActivity.class).putExtra("record",record.id)));}Design.button(body,"Reload this day",false,()->{if(operation==null){allSleep=noTravel=false;draftKey=draftFingerprint="";load();}});if(prior!=null)Design.button(body,"Remove this day confirmation",false,this::remove);method(body);
        LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty())Design.text(footer,error,13,500,Design.BROWN);Design.button(footer,operation==null?"Confirm complete day":"Saving confirmation…",true,this::save).setEnabled(!loading&&operation==null&&day.reviewable(System.currentTimeMillis()));Design.button(footer,"Keep day unknown / back",false,this::back).setEnabled(operation==null);}
    private String time(long at,SRIModel.Day day){return at==day.end?"24:00":RecordUi.preciseClock(this,at,day.zone);}
    private void open(LocalDate date){if(operation!=null)return;LocalDate today=LocalDate.now(zone);if(!date.isBefore(today)||date.isBefore(today.minusDays(30))){error="Choose one of the past 30 completed calendar days.";render();return;}selected=date;reviewing=true;allSleep=noTravel=false;draftKey=draftFingerprint="";snapshot=null;error="";load();}
    private void calendar(){if(operation!=null)return;if(calendar!=null)calendar.close();calendar=new RecordCalendar(this,"Review a complete day",selected,null,this::open,null);}
    private void save(){if(operation!=null||snapshot==null||loading)return;if(!allSleep||!noTravel){error="Confirm both statements only if they are true. Otherwise leave this day unknown.";render();return;}String token=UUID.randomUUID().toString();operation=token;SRIReviews.Snapshot reviewed=snapshot;Records.Factory pinned=records;SRIReviews.Factory prefs=preferences;PlanOperations.start(this,token,app->{SRIReviews.confirm(app,pinned,prefs,reviewed.selected,reviewed.saved.stamp(),true,true);return "Complete day confirmed.";});observe();render();}
    private void remove(){if(operation!=null||snapshot==null)return;String token=UUID.randomUUID().toString();operation=token;SRIReviews.Snapshot reviewed=snapshot;SRIReviews.Factory prefs=preferences;PlanOperations.start(this,token,app->{SRIReviews.remove(app,prefs,reviewed.selected.key(),reviewed.saved.stamp());return "Day confirmation removed. Its unrecorded time is unknown again.";});observe();render();}
    private void observe(){main.removeCallbacks(poll);if(operation==null||!resumed)return;PlanOperations.Operation result=PlanOperations.start(this,operation,app->{throw new IllegalStateException("The previous confirmation operation is unavailable. Reload and review before saving again.");});if(!result.done){main.postDelayed(poll,100);return;}PlanOperations.forget(operation);operation=null;error=result.error==null?result.notice:result.error;allSleep=noTravel=false;draftKey=draftFingerprint="";load();}
    private final Runnable watch=new Runnable(){public void run(){if(!resumed)return;if(operation==null&&!loading&&snapshot!=null&&seenChanges!=SRIReviews.generation())load();main.postDelayed(this,1000);}};
    private final Runnable poll=this::observe;
    private void method(LinearLayout body){Design.item(body,"info","Method and limitations",null,()->{if(explanation!=null)explanation.dismiss();explanation=SleepPicker.message(this,"Diary-based SRI","Phillips and colleagues (Scientific Reports, 2017) compare whether sleep/wake states are the same 24 hours apart. This app samples minute centers and computes 100 × (2 × same / compared − 1), from unchanged complete-day diary confirmations only. The possible range is −100 to 100; no clinical category is assigned. Seven adjacent day pairs is this app’s minimum, not a validated study protocol. Missing days, travel and clock-change days are excluded. Recorded sleep is not automatically proven sleep, so your complete-day review is necessary.");});Design.button(body,"Read the primary method",false,()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(SRIModel.METHOD)));}catch(RuntimeException unavailable){error="Open DOI 10.1038/s41598-017-03171-4 in a browser.";render();}});}
    private void back(){if(operation!=null)return;if(reviewing){reviewing=false;error="";render();}else finish();}@android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("zone",zone.getId());state.putString("selected",selected.toString());state.putBoolean("reviewing",reviewing);state.putBoolean("allSleep",allSleep);state.putBoolean("noTravel",noTravel);state.putString("draftFingerprint",draftFingerprint);state.putString("draftKey",draftKey);state.putString("error",error);state.putString("operation",operation);}@Override protected void onDestroy(){generation++;main.removeCallbacks(poll);main.removeCallbacks(watch);reader.shutdownNow();if(calendar!=null)calendar.close();if(explanation!=null)explanation.dismiss();super.onDestroy();}@Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
